import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = HouseKeepingPlugin.NAME,
	description = "Suggests bank items you have outgrown, can store in your POH, or no longer need",
	tags = {"bank", "poh", "quest", "storage", "cleanup"}
)
@PluginDependency(BankTagsPlugin.class)
public class HouseKeepingPlugin extends Plugin
{
	static final String NAME = "House Keeping";

	// Virtual bank tags: one with every suggestion, and one per category
	private static final String BANK_TAG = NAME;
	private static final Map<Category, String> CATEGORY_BANK_TAGS = Arrays.stream(Category.values())
		.collect(Collectors.toMap(c -> c, c -> BANK_TAG + " - " + c.getDisplayName(),
			(a, b) -> a, () -> new EnumMap<>(Category.class)));

	// Every quest a rule depends on; their states are read on login and whenever the bank opens
	private static final Set<Quest> TRACKED_QUESTS = Stream.of(
			BookcaseBooks.ITEMS.values().stream().map(BookcaseBooks.Entry::getQuest),
			JunkItems.ITEMS.values().stream().map(JunkItems.Entry::getNeededFor),
			QuestItems.ITEMS.values().stream().flatMap(Set::stream))
		.flatMap(quests -> quests)
		.filter(Objects::nonNull)
		.collect(Collectors.toCollection(() -> EnumSet.noneOf(Quest.class)));

	@Inject
	private Client client;

	@Inject
	private HouseKeepingConfig config;

	@Inject
	private ProfileStore store;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HouseKeepingOverlay overlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsService bankTagsService;

	private final SuggestionEngine engine = new SuggestionEngine();

	private HouseKeepingPanel panel;
	private NavigationButton navButton;

	/**
	 * Non-ignored suggestions passing the config filters, keyed by item id. Read every frame by the overlay.
	 */
	@Getter
	private volatile Map<Integer, Suggestion> visibleSuggestions = Collections.emptyMap();

	private volatile boolean refreshPending;
	// Inventory item id to its canonical (unnoted) id; only the set of items matters, not quantities
	private Map<Integer, Integer> inventoryItems = Collections.emptyMap();
	private boolean questsDirty;
	private Set<Quest> finishedQuests = Collections.emptySet();
	private final Map<Skill, Integer> knownLevels = new EnumMap<>(Skill.class);

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);

		panel = new HouseKeepingPanel(itemManager, this::ignore, this::restore, this::showInBank);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip(NAME)
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Ignored items never match: visibleSuggestions only holds what the player still wants to see.
		// A lambda, not a method reference, so each check reads the latest map.
		tagManager.registerTag(BANK_TAG, itemId -> visibleSuggestions.containsKey(itemId));
		CATEGORY_BANK_TAGS.forEach((category, tag) -> tagManager.registerTag(tag, itemId ->
		{
			Suggestion suggestion = visibleSuggestions.get(itemId);
			return suggestion != null && suggestion.getCategory() == category;
		}));

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			store.load();
			questsDirty = true;
			refreshPending = true;
		}

		// Bank open/close events only cover changes from now on, so pick up a bank that's already open
		clientThread.invoke(() -> setBankOpen(client.getWidget(InterfaceID.Bankmain.ITEMS) != null));
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		clientThread.invoke(() ->
		{
			if (isOurBankTag(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
		});
		tagManager.unregisterTag(BANK_TAG);
		CATEGORY_BANK_TAGS.values().forEach(tagManager::unregisterTag);
		panel = null;
		navButton = null;
		visibleSuggestions = Collections.emptyMap();
		finishedQuests = Collections.emptySet();
		inventoryItems = Collections.emptyMap();
		knownLevels.clear();
		store.clear();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		store.load();
		knownLevels.clear();
		questsDirty = true;
		refreshPending = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			questsDirty = true;
			refreshPending = true;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Quest states are read on the next tick: scripts can't run from inside this callback
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			questsDirty = true;
			refreshPending = true;
			setBankOpen(true);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			setBankOpen(false);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			Map<Integer, Integer> carried = new HashMap<>();
			for (Item item : event.getItemContainer().getItems())
			{
				if (item.getId() > 0)
				{
					carried.computeIfAbsent(item.getId(), itemManager::canonicalize);
				}
			}
			// Quantities change constantly while skilling; only re-evaluate when the items themselves change
			if (!carried.keySet().equals(inventoryItems.keySet()))
			{
				inventoryItems = carried;
				refreshPending = true;
			}
			return;
		}

		if (event.getContainerId() != InventoryID.BANK)
		{
			return;
		}

		Map<Integer, Integer> items = new LinkedHashMap<>();
		for (Item item : event.getItemContainer().getItems())
		{
			// Placeholders have quantity 0; fillers are just empty slots
			if (item.getId() <= 0 || item.getQuantity() <= 0 || item.getId() == ItemID.BANK_FILLER)
			{
				continue;
			}
			items.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
		}
		store.setBank(items);
		refreshPending = true;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Fires on every xp drop, so only refresh when a real level actually changes
		Integer previous = knownLevels.put(event.getSkill(), event.getLevel());
		if (previous == null || previous != event.getLevel())
		{
			refreshPending = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (HouseKeepingConfig.GROUP.equals(event.getGroup()))
		{
			refreshPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (refreshPending)
		{
			refreshPending = false;
			refresh();
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.ignoreMenuOption())
		{
			return;
		}

		// Every entry of an item's menu points at the same item, so the first one tells us which it is
		MenuEntry itemEntry = Arrays.stream(event.getMenuEntries())
			.filter(this::isMarkedItemWidget)
			.findFirst()
			.orElse(null);
		Suggestion suggestion = itemEntry == null ? null : visibleSuggestions.get(itemEntry.getItemId());
		if (suggestion == null)
		{
			return;
		}

		// Purely client-side: only updates the plugin's own ignore list. The suggestion's id is
		// the unnoted one, so ignoring a noted stack ignores the item itself.
		client.getMenu().createMenuEntry(1)
			.setOption("Ignore suggestion")
			.setTarget(ColorUtil.wrapWithColorTag(NAME, getColor(suggestion.getCategory())))
			.setType(MenuAction.RUNELITE)
			.onClick(e -> ignore(suggestion.getItemId()));
	}

	/**
	 * Whether the menu entry is for an item in a place where markers are drawn.
	 */
	private boolean isMarkedItemWidget(MenuEntry entry)
	{
		int widget = entry.getParam1();
		boolean bankItem = widget == InterfaceID.Bankmain.ITEMS;
		boolean inventoryItem = widget == InterfaceID.Inventory.ITEMS || widget == InterfaceID.Bankside.ITEMS;
		return (bankItem && config.highlightBank()) || (inventoryItem && config.highlightInventory());
	}

	Color getColor(Category category)
	{
		switch (category)
		{
			case OUTGROWN:
				return config.outgrownColor();
			case QUEST:
				return config.questColor();
			case POH:
				return config.pohColor();
			case JUNK:
			default:
				return config.junkColor();
		}
	}

	/**
	 * Toggles the House Keeping bank tab, for one category or everything when the category is null.
	 */
	private void showInBank(Category category)
	{
		String tag = category == null ? BANK_TAG : CATEGORY_BANK_TAGS.get(category);
		clientThread.invoke(() ->
		{
			if (client.getWidget(InterfaceID.Bankmain.ITEMS) == null)
			{
				return;
			}
			if (tag.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			else
			{
				bankTagsService.openBankTag(tag, BankTagsService.OPTION_NO_LAYOUT);
			}
		});
	}

	private static boolean isOurBankTag(String tag)
	{
		return BANK_TAG.equals(tag) || CATEGORY_BANK_TAGS.containsValue(tag);
	}

	private void setBankOpen(boolean open)
	{
		HouseKeepingPanel currentPanel = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (currentPanel != null)
			{
				currentPanel.setBankOpen(open);
			}
		});
	}

	private void ignore(int itemId)
	{
		store.setIgnored(itemId, true);
		refreshPending = true;
	}

	private void restore(int itemId)
	{
		store.setIgnored(itemId, false);
		refreshPending = true;
	}

	private void refresh()
	{
		Map<Integer, Integer> bank = store.getBank();
		Set<Integer> ignored = store.getIgnored();
		Set<Category> enabled = enabledCategories();

		// Inventory items get markers too, but the panel and counter only describe the bank
		Map<Integer, Integer> carried = inventoryItems;
		Set<Integer> itemIds = new LinkedHashSet<>(bank.keySet());
		itemIds.addAll(carried.values());

		Map<Integer, Suggestion> visible = new HashMap<>();
		List<ItemSuggestion> active = new ArrayList<>();
		List<ItemSuggestion> ignoredItems = new ArrayList<>();
		for (Suggestion suggestion : engine.evaluate(itemIds, buildPlayerState()))
		{
			int itemId = suggestion.getItemId();
			if (!SuggestionEngine.isVisible(suggestion, enabled, config.showMaybe()))
			{
				continue;
			}

			boolean isIgnored = ignored.contains(itemId);
			if (!isIgnored)
			{
				visible.put(itemId, suggestion);
			}

			Integer quantity = bank.get(itemId);
			if (quantity != null)
			{
				ItemSuggestion item = describe(suggestion, quantity);
				(isIgnored ? ignoredItems : active).add(item);
			}
		}

		// Noted items in the inventory are drawn with their noted id
		for (Map.Entry<Integer, Integer> entry : carried.entrySet())
		{
			Suggestion suggestion = visible.get(entry.getValue());
			if (suggestion != null)
			{
				visible.putIfAbsent(entry.getKey(), suggestion);
			}
		}
		boolean changed = !visible.equals(visibleSuggestions);
		visibleSuggestions = Collections.unmodifiableMap(visible);

		// Re-filter an open House Keeping bank tab, e.g. after an item was ignored
		String activeTag = bankTagsService.getActiveTag();
		if (changed && isOurBankTag(activeTag))
		{
			bankTagsService.openBankTag(activeTag, BankTagsService.OPTION_NO_LAYOUT);
		}

		boolean hasSnapshot = !bank.isEmpty();
		boolean showCounter = config.showCounter();
		Map<Category, Color> colors = categoryColors();
		HouseKeepingPanel currentPanel = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (currentPanel != null)
			{
				currentPanel.update(active, ignoredItems, hasSnapshot, showCounter, colors);
			}
		});
	}

	private Set<Category> enabledCategories()
	{
		Set<Category> enabled = EnumSet.noneOf(Category.class);
		if (config.showOutgrown())
		{
			enabled.add(Category.OUTGROWN);
		}
		if (config.showQuest())
		{
			enabled.add(Category.QUEST);
		}
		if (config.showPoh())
		{
			enabled.add(Category.POH);
		}
		if (config.showJunk())
		{
			enabled.add(Category.JUNK);
		}
		return enabled;
	}

	private Map<Category, Color> categoryColors()
	{
		Map<Category, Color> colors = new EnumMap<>(Category.class);
		for (Category category : Category.values())
		{
			colors.put(category, getColor(category));
		}
		return colors;
	}

	private ItemSuggestion describe(Suggestion suggestion, int quantity)
	{
		int itemId = suggestion.getItemId();
		ItemComposition composition = itemManager.getItemComposition(itemId);

		// Show whichever is worth more: selling on the GE or high alching
		long ge = itemManager.getItemPrice(itemId);
		long ha = composition.getHaPrice();
		long each = Math.max(ge, ha);
		String source = null;
		if (each > 0)
		{
			source = ge >= ha ? "GE" : "HA";
		}

		return new ItemSuggestion(suggestion, composition.getName(), quantity, each * quantity, source);
	}

	private PlayerState buildPlayerState()
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (OutgrownItems.Entry entry : OutgrownItems.ITEMS.values())
		{
			for (Skill skill : entry.getLevels().keySet())
			{
				levels.computeIfAbsent(skill, client::getRealSkillLevel);
			}
		}

		if (questsDirty)
		{
			questsDirty = false;
			Set<Quest> finished = EnumSet.noneOf(Quest.class);
			for (Quest quest : TRACKED_QUESTS)
			{
				if (quest.getState(client) == QuestState.FINISHED)
				{
					finished.add(quest);
				}
			}
			finishedQuests = finished;
		}

		return new PlayerState(levels, finishedQuests, builtStorage());
	}

	private Set<PohStorage.Storage> builtStorage()
	{
		Set<PohStorage.Storage> built = EnumSet.noneOf(PohStorage.Storage.class);
		// Each chest also holds everything the smaller chests hold; the enum is ordered smallest first
		HouseKeepingConfig.TreasureChest chest = config.treasureChest();
		if (chest.compareTo(HouseKeepingConfig.TreasureChest.OAK) >= 0)
		{
			built.add(PohStorage.Storage.TREASURE_CHEST_OAK);
		}
		if (chest.compareTo(HouseKeepingConfig.TreasureChest.TEAK) >= 0)
		{
			built.add(PohStorage.Storage.TREASURE_CHEST_TEAK);
		}
		if (chest == HouseKeepingConfig.TreasureChest.MAHOGANY)
		{
			built.add(PohStorage.Storage.TREASURE_CHEST_MAHOGANY);
		}
		if (config.armourCase())
		{
			built.add(PohStorage.Storage.ARMOUR_CASE);
		}
		if (config.capeRack())
		{
			built.add(PohStorage.Storage.CAPE_RACK);
		}
		if (config.magicWardrobe())
		{
			built.add(PohStorage.Storage.MAGIC_WARDROBE);
		}
		if (config.fancyDressBox())
		{
			built.add(PohStorage.Storage.FANCY_DRESS_BOX);
		}
		if (config.toyBox())
		{
			built.add(PohStorage.Storage.TOY_BOX);
		}
		return built;
	}

	@Provides
	HouseKeepingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HouseKeepingConfig.class);
	}
}

package com.housekeeping;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Forgiving search over suggestion names and reasons. Case, spaces and punctuation are ignored, query
 * words may come in any order, initials match ("bdm" finds "Blue dragon mask"), and longer words
 * tolerate a typo or two. Typo matches score at most {@link #TYPO_MATCH_MAX} so callers can hide them
 * whenever something matched exactly.
 */
final class ItemSearch
{
	static final int NO_MATCH = 0;
	/**
	 * Scores at or below this come from typo-tolerant matching; everything above matched exactly.
	 */
	static final int TYPO_MATCH_MAX = 40;

	private ItemSearch()
	{
	}

	/**
	 * @return how well the query matches, higher is better, or {@link #NO_MATCH}
	 */
	static int score(String query, String name, String reason)
	{
		String compactQuery = compact(query);
		if (compactQuery.isEmpty())
		{
			return NO_MATCH;
		}

		String compactName = compact(name);
		List<String> tokens = tokens(query);

		if (compactName.equals(compactQuery))
		{
			return 100;
		}
		if (compactName.startsWith(compactQuery))
		{
			return 95;
		}
		if (compactName.contains(compactQuery))
		{
			return 90;
		}
		if (tokens.stream().allMatch(compactName::contains))
		{
			return 80;
		}
		if (compactQuery.length() >= 2 && initials(name).startsWith(compactQuery))
		{
			return 70;
		}

		String compactReason = compact(reason);
		if (compactReason.contains(compactQuery) || tokens.stream().allMatch(compactReason::contains))
		{
			return 50;
		}

		int distance = fuzzyDistance(tokens, compactName);
		if (distance < 0 && tokens.size() > 1)
		{
			// "spot tiercape": the words may not line up with the name's, so try the query as a whole
			distance = fuzzyDistance(List.of(compactQuery), compactName);
		}
		if (distance >= 0)
		{
			return Math.max(1, TYPO_MATCH_MAX - distance * 5);
		}
		return NO_MATCH;
	}

	/**
	 * Lower case letters and digits only, so "Fire  Cape", "fire-cape" and "firecape" all compare equal.
	 */
	static String compact(String text)
	{
		StringBuilder out = new StringBuilder(text.length());
		for (char c : text.toLowerCase(Locale.ROOT).toCharArray())
		{
			if (Character.isLetterOrDigit(c))
			{
				out.append(c);
			}
		}
		return out.toString();
	}

	private static List<String> tokens(String query)
	{
		List<String> tokens = new ArrayList<>();
		for (String word : query.trim().split("\\s+"))
		{
			String token = compact(word);
			if (!token.isEmpty())
			{
				tokens.add(token);
			}
		}
		return tokens;
	}

	private static String initials(String name)
	{
		StringBuilder out = new StringBuilder();
		for (String word : name.toLowerCase(Locale.ROOT).split("[^\\p{L}\\p{N}]+"))
		{
			if (!word.isEmpty())
			{
				out.append(word.charAt(0));
			}
		}
		return out.toString();
	}

	/**
	 * Sum of each token's closest approximate match anywhere in the text, or -1 if any token is too far off.
	 */
	private static int fuzzyDistance(List<String> tokens, String text)
	{
		int total = 0;
		for (String token : tokens)
		{
			int distance = substringDistance(token, text);
			if (distance > allowedTypos(token.length()))
			{
				return -1;
			}
			total += distance;
		}
		return total;
	}

	private static int allowedTypos(int length)
	{
		if (length <= 3)
		{
			return 0;
		}
		return length <= 5 ? 1 : 2;
	}

	/**
	 * Smallest edit distance between the pattern and any substring of the text (Sellers' algorithm).
	 */
	static int substringDistance(String pattern, String text)
	{
		int[] previous = new int[text.length() + 1];
		int[] current = new int[text.length() + 1];
		// Row 0 stays all zeroes: a match may start anywhere in the text
		for (int i = 1; i <= pattern.length(); i++)
		{
			current[0] = i;
			for (int j = 1; j <= text.length(); j++)
			{
				int substitution = previous[j - 1] + (pattern.charAt(i - 1) == text.charAt(j - 1) ? 0 : 1);
				current[j] = Math.min(substitution, Math.min(previous[j], current[j - 1]) + 1);
			}
			int[] swap = previous;
			previous = current;
			current = swap;
		}

		int best = Integer.MAX_VALUE;
		for (int distance : previous)
		{
			best = Math.min(best, distance);
		}
		return best;
	}
}

package com.housekeeping;

import javax.annotation.Nullable;
import lombok.Value;

/**
 * A suggestion resolved against the bank snapshot, ready for display.
 */
@Value
class ItemSuggestion
{
	Suggestion suggestion;
	String name;
	int quantity;
	/**
	 * Value of the whole stack, using the higher of the GE price and high alch value.
	 */
	long value;
	/**
	 * "GE" or "HA", naming where {@link #value} came from; null when the item is worthless.
	 */
	@Nullable
	String valueSource;
}

package com.housekeeping;

import com.housekeeping.data.PohStorage;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Snapshot of the account facts the suggestion rules depend on. Built on the client thread,
 * then read freely so the rules stay independent of {@link net.runelite.api.Client}.
 */
@Value
public class PlayerState
{
	Map<Skill, Integer> levels;
	Set<Quest> finishedQuests;
	/**
	 * Costume room storage the player has told us they built.
	 */
	Set<PohStorage.Storage> pohStorage;

	public int getLevel(Skill skill)
	{
		return levels.getOrDefault(skill, 1);
	}

	public boolean isFinished(Quest quest)
	{
		return finishedQuests.contains(quest);
	}
}

package com.housekeeping;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;

/**
 * Per-account state, persisted in the RuneScape profile config so it survives restarts.
 */
@Singleton
public class ProfileStore
{
	private static final String BANK_KEY = "bank";
	private static final String IGNORED_KEY = "ignored";

	private final ConfigManager configManager;
	private final Gson gson;

	/**
	 * Item id to quantity, in bank order. Empty until the bank has been opened once.
	 */
	@Getter
	private volatile Map<Integer, Integer> bank = Collections.emptyMap();
	private final Set<Integer> ignored = ConcurrentHashMap.newKeySet();

	@Inject
	ProfileStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void load()
	{
		// Saved as {"itemId": quantity, ...} in bank order, and [itemId, ...]
		Map<Integer, Integer> savedBank = new LinkedHashMap<>();
		JsonObject bankJson = read(BANK_KEY, JsonObject.class);
		if (bankJson != null)
		{
			for (Map.Entry<String, JsonElement> entry : bankJson.entrySet())
			{
				savedBank.put(Integer.parseInt(entry.getKey()), entry.getValue().getAsInt());
			}
		}
		bank = Collections.unmodifiableMap(savedBank);

		ignored.clear();
		int[] savedIgnored = read(IGNORED_KEY, int[].class);
		if (savedIgnored != null)
		{
			for (int itemId : savedIgnored)
			{
				ignored.add(itemId);
			}
		}
	}

	public void clear()
	{
		bank = Collections.emptyMap();
		ignored.clear();
	}

	public void setBank(Map<Integer, Integer> items)
	{
		if (items.equals(bank))
		{
			return;
		}
		bank = Collections.unmodifiableMap(items);
		configManager.setRSProfileConfiguration(HouseKeepingConfig.GROUP, BANK_KEY, gson.toJson(items));
	}

	public Set<Integer> getIgnored()
	{
		return Collections.unmodifiableSet(ignored);
	}

	public void setIgnored(int itemId, boolean ignore)
	{
		boolean changed = ignore ? ignored.add(itemId) : ignored.remove(itemId);
		if (changed)
		{
			configManager.setRSProfileConfiguration(HouseKeepingConfig.GROUP, IGNORED_KEY, gson.toJson(ignored));
		}
	}

	private <T> T read(String key, Class<T> type)
	{
		String json = configManager.getRSProfileConfiguration(HouseKeepingConfig.GROUP, key);
		try
		{
			return json == null ? null : gson.fromJson(json, type);
		}
		catch (JsonParseException | NumberFormatException e)
		{
			// A damaged entry only costs the cached bank or ignore list; the bank is re-read when opened
			return null;
		}
	}
}

