import com.housekeeping.Category;
import com.housekeeping.Confidence;
import com.housekeeping.PlayerState;
import com.housekeeping.Suggestion;
import com.housekeeping.data.JunkItems;
import net.runelite.api.Quest;

public class JunkRule implements SuggestionRule
{
	@Override
	public Suggestion evaluate(int itemId, PlayerState state)
	{
		JunkItems.Entry entry = JunkItems.ITEMS.get(itemId);
		if (entry == null)
		{
			return null;
		}

		Quest quest = entry.getNeededFor();
		if (quest != null && state.isFinished(quest))
		{
			return new Suggestion(itemId, Category.JUNK, Confidence.HIGH,
				"No further use now that " + quest.getName() + " is complete");
		}
		return new Suggestion(itemId, Category.JUNK, entry.getConfidence(), entry.getReason());
	}
}

package com.housekeeping.rules;

import com.housekeeping.Category;
import com.housekeeping.Confidence;
import com.housekeeping.PlayerState;
import com.housekeeping.Suggestion;
import com.housekeeping.data.PohStorage;
import java.util.Set;

public class PohStorageRule implements SuggestionRule
{
	@Override
	public Suggestion evaluate(int itemId, PlayerState state)
	{
		Set<PohStorage.Storage> storages = PohStorage.ITEMS.get(itemId);
		if (storages == null)
		{
			return null;
		}

		for (PohStorage.Storage storage : storages)
		{
			if (state.getPohStorage().contains(storage))
			{
				return new Suggestion(itemId, Category.POH, Confidence.HIGH,
					"Can be stored in your POH " + storage.getDisplayName());
			}
		}
		return null;
	}
}

package com.housekeeping.rules;

import com.housekeeping.Category;
import com.housekeeping.Confidence;
import com.housekeeping.PlayerState;
import com.housekeeping.Suggestion;
import com.housekeeping.data.QuestItems;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Quest;

public class QuestItemRule implements SuggestionRule
{
	@Override
	public Suggestion evaluate(int itemId, PlayerState state)
	{
		Set<Quest> quests = QuestItems.ITEMS.get(itemId);
		if (quests == null || !quests.stream().allMatch(state::isFinished))
		{
			return null;
		}

		String names = quests.stream().map(Quest::getName).collect(Collectors.joining(", "));
		return new Suggestion(itemId, Category.QUEST, Confidence.HIGH,
			"No further use now that " + names + (quests.size() > 1 ? " are" : " is") + " complete");
	}
}

package com.housekeeping.rules;

import com.housekeeping.Category;
import com.housekeeping.PlayerState;
import com.housekeeping.Suggestion;
import com.housekeeping.data.OutgrownItems;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Skill;

public class SkillOutgrownRule implements SuggestionRule
{
	@Override
	public Suggestion evaluate(int itemId, PlayerState state)
	{
		OutgrownItems.Entry entry = OutgrownItems.ITEMS.get(itemId);
		if (entry == null)
		{
			return null;
		}

		for (Map.Entry<Skill, Integer> level : entry.getLevels().entrySet())
		{
			if (state.getLevel(level.getKey()) < level.getValue())
			{
				return null;
			}
		}

		String levels = entry.getLevels().entrySet().stream()
			.map(e -> e.getValue() + "+ " + e.getKey().getName())
			.collect(Collectors.joining(" and "));
		return new Suggestion(itemId, Category.OUTGROWN, entry.getConfidence(), "Outgrown: you have " + levels);
	}
}

package com.housekeeping.rules;

import com.housekeeping.PlayerState;
import com.housekeeping.Suggestion;
import javax.annotation.Nullable;

public interface SuggestionRule
{
	/**
	 * @return a suggestion for the item, or null if this rule has nothing to say about it
	 */
	@Nullable
	Suggestion evaluate(int itemId, PlayerState state);
}

