package com.housekeeping;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ItemSearchTest
{
	private static int score(String query, String name)
	{
		return ItemSearch.score(query, name, "");
	}

	@Test
	public void ignoresCaseSpacesAndPunctuation()
	{
		assertEquals(100, score("FIRE CAPE", "Fire cape"));
		assertEquals(100, score("firecape", "Fire cape"));
		assertEquals(100, score("adamant helm h5", "Adamant helm (h5)"));
		assertTrue(score("gianne", "Gianne's cook book") > ItemSearch.NO_MATCH);
	}

	@Test
	public void matchesPartOfLongerNames()
	{
		assertEquals(95, score("spottier", "Spottier cape"));
		assertEquals(90, score("cape", "Spottier cape"));
	}

	@Test
	public void matchesWordsInAnyOrder()
	{
		assertEquals(80, score("cape fire", "Fire cape"));
	}

	@Test
	public void matchesInitials()
	{
		assertEquals(70, score("bdm", "Blue dragon mask"));
	}

	@Test
	public void toleratesTypos()
	{
		assertTrue(score("spotier cape", "Spottier cape") > ItemSearch.NO_MATCH);
		assertTrue(score("baguete", "Stale baguette") > ItemSearch.NO_MATCH);
		assertTrue(score("dragn mask", "Blue dragon mask") > ItemSearch.NO_MATCH);
		// Short words must match exactly, or "axe" would also find "ace"
		assertEquals(ItemSearch.NO_MATCH, score("axe", "Ace of spades"));
	}

	@Test
	public void closerMatchesRankHigher()
	{
		assertTrue(score("fire cape", "Fire cape") > score("fire cap", "Fire cape"));
		assertTrue(score("cape", "Fire cape") > score("cape", "Bronze axe"));
		assertTrue(score("baguette", "Stale baguette") > score("baguete", "Stale baguette"));
	}

	@Test
	public void fallsBackToTheReason()
	{
		assertEquals(50, ItemSearch.score("watchtower", "Old robe", "No further use now that Watchtower is complete"));
		assertEquals(50, ItemSearch.score("toy box", "Bunny ears", "Can be stored in your POH toy box"));
		// A name match always outranks a reason match
		assertTrue(score("cape", "Fire cape") > ItemSearch.score("cape rack", "Bunny ears", "...cape rack"));
	}

	@Test
	public void typoMatchesStayBelowExactOnes()
	{
		// "cane" is one letter off "cape", so it only counts as a typo match the panel can hide
		int typo = score("cape", "Rune cane");
		assertTrue(typo > ItemSearch.NO_MATCH && typo <= ItemSearch.TYPO_MATCH_MAX);
		assertTrue(score("cape", "Fire cape") > ItemSearch.TYPO_MATCH_MAX);
		assertTrue(score("bdm", "Blue dragon mask") > ItemSearch.TYPO_MATCH_MAX);
		assertTrue(ItemSearch.score("cape rack", "Bunny ears", "...cape rack") > ItemSearch.TYPO_MATCH_MAX);
		assertTrue(score("spotier cape", "Spottier cape") <= ItemSearch.TYPO_MATCH_MAX);
	}

	@Test
	public void emptyQueryMatchesNothing()
	{
		assertEquals(ItemSearch.NO_MATCH, score("   ", "Fire cape"));
	}

	@Test
	public void substringDistanceFindsBestWindow()
	{
		assertEquals(0, ItemSearch.substringDistance("cape", "spottiercape"));
		assertEquals(1, ItemSearch.substringDistance("spotier", "spottiercape"));
	}
}

package com.housekeeping;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import com.housekeeping.data.PohStorage;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SuggestionEngineTest
{
	private final SuggestionEngine engine = new SuggestionEngine();

	private static PlayerState state(Map<Skill, Integer> levels, Set<Quest> quests)
	{
		return new PlayerState(levels, quests, Set.of());
	}

	private static PlayerState built(PohStorage.Storage... storage)
	{
		return new PlayerState(Map.of(), Set.of(), Set.of(storage));
	}

	private List<Suggestion> evaluate(int itemId, PlayerState state)
	{
		return engine.evaluate(Collections.singletonList(itemId), state);
	}

	@Test
	public void rawShrimpOutgrownAtHighFishingAndCooking()
	{
		PlayerState maxed = state(ImmutableMap.of(Skill.FISHING, 99, Skill.COOKING, 99), Set.of());
		List<Suggestion> result = evaluate(ItemID.RAW_SHRIMP, maxed);

		assertEquals(1, result.size());
		assertEquals(Category.OUTGROWN, result.get(0).getCategory());
		assertEquals(Confidence.HIGH, result.get(0).getConfidence());
	}

	@Test
	public void rawShrimpKeptUntilEverySkillIsMet()
	{
		PlayerState lowCooking = state(ImmutableMap.of(Skill.FISHING, 99, Skill.COOKING, 20), Set.of());
		assertTrue(evaluate(ItemID.RAW_SHRIMP, lowCooking).isEmpty());
	}

	@Test
	public void unknownItemHasNoSuggestion()
	{
		PlayerState maxed = state(ImmutableMap.of(Skill.FISHING, 99, Skill.COOKING, 99), Set.of());
		assertTrue(evaluate(ItemID.COINS, maxed).isEmpty());
	}

	@Test
	public void burntFoodIsJunk()
	{
		List<Suggestion> result = evaluate(ItemID.BURNT_SHARK, state(Map.of(), Set.of()));

		assertEquals(1, result.size());
		assertEquals(Category.JUNK, result.get(0).getCategory());
	}

	@Test
	public void wikiJunkIsJunk()
	{
		List<Suggestion> result = evaluate(ItemID.FLIER_PRIF, state(Map.of(), Set.of()));

		assertEquals(1, result.size());
		assertEquals(Category.JUNK, result.get(0).getCategory());
		assertEquals(Confidence.HIGH, result.get(0).getConfidence());
	}

	@Test
	public void questJunkIsMaybeUntilQuestFinished()
	{
		List<Suggestion> before = evaluate(ItemID.GROUND_BAT_BONES, state(Map.of(), Set.of()));
		assertEquals(Confidence.MAYBE, before.get(0).getConfidence());

		List<Suggestion> after = evaluate(ItemID.GROUND_BAT_BONES, state(Map.of(), ImmutableSet.of(Quest.WATCHTOWER)));
		assertEquals(Confidence.HIGH, after.get(0).getConfidence());
		assertEquals(Category.JUNK, after.get(0).getCategory());
	}

	@Test
	public void bookcaseBookNeedsFinishedQuest()
	{
		assertTrue(evaluate(ItemID.BAXTORIAN_BOOK_WATERFALL_QUEST, state(Map.of(), Set.of())).isEmpty());

		Set<Quest> done = ImmutableSet.of(Quest.WATERFALL_QUEST);
		List<Suggestion> result = evaluate(ItemID.BAXTORIAN_BOOK_WATERFALL_QUEST, state(Map.of(), done));
		assertEquals(1, result.size());
		assertEquals(Category.JUNK, result.get(0).getCategory());
	}

	@Test
	public void nonQuestBookAlwaysRetrievable()
	{
		List<Suggestion> result = evaluate(ItemID.ABLENKIAN_ESCAPE, state(Map.of(), Set.of()));

		assertEquals(1, result.size());
		assertEquals(Confidence.HIGH, result.get(0).getConfidence());
	}

	@Test
	public void functionalBookIsOnlyAMaybe()
	{
		List<Suggestion> result = evaluate(ItemID.COLLECTION_LOG, state(Map.of(), Set.of()));

		assertEquals(1, result.size());
		assertEquals(Confidence.MAYBE, result.get(0).getConfidence());
	}

	@Test
	public void questItemObsoleteOnceQuestFinished()
	{
		assertTrue(evaluate(ItemID.DOOMION_AMULET, state(Map.of(), Set.of())).isEmpty());

		List<Suggestion> result = evaluate(ItemID.DOOMION_AMULET, state(Map.of(), ImmutableSet.of(Quest.UNDERGROUND_PASS)));
		assertEquals(1, result.size());
		assertEquals(Category.QUEST, result.get(0).getCategory());
	}

	@Test
	public void questItemKeptUntilEveryQuestFinished()
	{
		Set<Quest> onlyOne = ImmutableSet.of(Quest.BIOHAZARD);
		assertTrue(evaluate(ItemID.ROTTENAPPLES, state(Map.of(), onlyOne)).isEmpty());

		Set<Quest> both = ImmutableSet.of(Quest.BIOHAZARD, Quest.MOURNINGS_END_PART_I);
		assertEquals(1, evaluate(ItemID.ROTTENAPPLES, state(Map.of(), both)).size());
	}

	@Test
	public void pohItemNeedsMatchingFurniture()
	{
		assertTrue(evaluate(ItemID.BUNNYEARS, built()).isEmpty());
		assertTrue(evaluate(ItemID.BUNNYEARS, built(PohStorage.Storage.CAPE_RACK)).isEmpty());

		List<Suggestion> result = evaluate(ItemID.BUNNYEARS, built(PohStorage.Storage.TOY_BOX));
		assertEquals(1, result.size());
		assertEquals(Category.POH, result.get(0).getCategory());
	}

	@Test
	public void treasureChestTierLimitsClueRewards()
	{
		// Frog slippers are a beginner clue reward, so any chest holds them
		assertEquals(1, evaluate(ItemID.FROG_SLIPPERS, built(PohStorage.Storage.TREASURE_CHEST_OAK)).size());
		// A master clue reward needs the mahogany chest
		assertTrue(evaluate(ItemID.BUCKET_HELM, built(PohStorage.Storage.TREASURE_CHEST_OAK)).isEmpty());
		assertEquals(1, evaluate(ItemID.BUCKET_HELM, built(PohStorage.Storage.TREASURE_CHEST_MAHOGANY)).size());
	}

	@Test
	public void maybeSuggestionsHiddenUnlessOptedIn()
	{
		Suggestion maybe = new Suggestion(ItemID.STEEL_AXE, Category.OUTGROWN, Confidence.MAYBE, "");
		Set<Category> all = EnumSet.allOf(Category.class);

		assertFalse(SuggestionEngine.isVisible(maybe, all, false));
		assertTrue(SuggestionEngine.isVisible(maybe, all, true));
		assertFalse(SuggestionEngine.isVisible(maybe, EnumSet.of(Category.JUNK), true));
	}
}
